import * as OurJsonization from "../src/jsonization";
import * as OurTypes from "../src/types";

test("RecorD deserializes Ok OK", () => {
  const jsonable = "ok";

  const literalOrError = OurJsonization.recordFromJsonable(
    jsonable
  );

  expect(literalOrError.error).toBeNull();
  const parsedLiteral = literalOrError.mustValue();

  expect(parsedLiteral).toStrictEqual(
    OurTypes.RecorD.Ok
  );
});

test("RecorD deserializes NotOk OK", () => {
  const jsonable = "not-ok";

  const literalOrError = OurJsonization.recordFromJsonable(
    jsonable
  );

  expect(literalOrError.error).toBeNull();
  const parsedLiteral = literalOrError.mustValue();

  expect(parsedLiteral).toStrictEqual(
    OurTypes.RecorD.NotOk
  );
});

test("RecorD deserialization fail", () => {
  const jsonable = "invalid-literal";

  const literalOrError = OurJsonization.recordFromJsonable(
    jsonable
  );

  expect(literalOrError.error.message).toStrictEqual(
    "Not a valid string representation of a literal of RecorD: invalid-literal"
  );
});

